import{_ as a,o as l,c as r,a2 as o}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"NVMe-Over-Fabrics Support for Ceph - Jonas Pfefferle, IBM","description":"","frontmatter":{"title":"NVMe-Over-Fabrics Support for Ceph - Jonas Pfefferle, IBM","date":"2023-05-05T00:00:00.000Z","updated":"2023-05-05T00:00:00.000Z","tags":["Ceph","NVMe","oF","分布式存储","高可用性","存储集群","软件定义存储","网络存储"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/NVMe-Over-Fabrics_Support_for_Ceph_-_Jonas_Pfefferle_IBM.md","filePath":"posts/2023/NVMe-Over-Fabrics_Support_for_Ceph_-_Jonas_Pfefferle_IBM.md","lastUpdated":1780459816000}'),i={name:"posts/2023/NVMe-Over-Fabrics_Support_for_Ceph_-_Jonas_Pfefferle_IBM.md"};function t(s,e,n,h,f,p){return l(),r("div",null,[...e[0]||(e[0]=[o('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议主题-ceph中nvme-over-fabrics-nvme-of-的支持概述" tabindex="-1">会议主题：Ceph中NVMe-over-Fabrics（NVMe-oF）的支持概述 <a class="header-anchor" href="#会议主题-ceph中nvme-over-fabrics-nvme-of-的支持概述" aria-label="Permalink to &quot;会议主题：Ceph中NVMe-over-Fabrics（NVMe-oF）的支持概述&quot;">​</a></h4><h4 id="主讲人-jonas-pfefferle-ibm研究" tabindex="-1">主讲人：Jonas Pfefferle，IBM研究 <a class="header-anchor" href="#主讲人-jonas-pfefferle-ibm研究" aria-label="Permalink to &quot;主讲人：Jonas Pfefferle，IBM研究&quot;">​</a></h4><h4 id="会议时间-具体日期" tabindex="-1">会议时间：[具体日期] <a class="header-anchor" href="#会议时间-具体日期" aria-label="Permalink to &quot;会议时间：[具体日期]&quot;">​</a></h4><h4 id="会议地点-具体地点" tabindex="-1">会议地点：[具体地点] <a class="header-anchor" href="#会议地点-具体地点" aria-label="Permalink to &quot;会议地点：[具体地点]&quot;">​</a></h4><h4 id="会议内容总结" tabindex="-1">会议内容总结： <a class="header-anchor" href="#会议内容总结" aria-label="Permalink to &quot;会议内容总结：&quot;">​</a></h4><ol><li><p><strong>背景介绍</strong>：</p><ul><li>Jonas介绍了NVMe-oF在Ceph中的应用，强调了其与现有RBD的区别和优势，包括提高互操作性、支持远程存储访问和利用DPU硬件加速。</li></ul></li><li><p><strong>技术细节</strong>：</p><ul><li><strong>架构</strong>：NVMe-oF网关作为中间层，将NVMe-oF协议转换为RADOS协议，支持TCP和RDMA传输。</li><li><strong>控制路径</strong>：使用Python编写的控制守护进程，通过gRPC进行配置管理，支持RBD图像到子系统命名空间的映射。</li><li><strong>数据路径</strong>：采用SPDK处理数据路径，支持多种块设备类型。</li><li><strong>多路径和故障转移</strong>：通过NVMe-oF多路径规范，实现网关组概念，支持配置持久化和多网关协同工作。</li></ul></li><li><p><strong>性能测试</strong>：</p><ul><li>表明NVMe-oF网关能够接近直接使用RBD的性能，并展示了单客户端和多客户端场景下的性能测试结果。</li></ul></li><li><p><strong>未来计划</strong>：</p><ul><li>实现发现服务，支持动态路径发现和更新。</li><li>考虑增加身份验证和加密功能，以及全局QoS控制。</li><li>探索在Ceph OSD中使用NVMe-oF的可能性。</li></ul></li><li><p><strong>项目状态</strong>：</p><ul><li>项目处于开发阶段，计划在Reef版本中发布初始版本，支持单网关配置。</li></ul></li><li><p><strong>参与者和资源</strong>：</p><ul><li>项目由多个公司和团队共同参与，提供代码库和社区支持。</li></ul></li></ol><h4 id="后续行动计划" tabindex="-1">后续行动计划： <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划：&quot;">​</a></h4><ul><li>优化性能和扩展性。</li><li>实现发现服务。</li><li>探索身份验证、加密和全局QoS控制。</li><li>加强社区合作。</li></ul><h4 id="会议结束" tabindex="-1">会议结束： <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束：&quot;">​</a></h4><ul><li>会议在提问和讨论环节后圆满结束，Jonas感谢所有参与者的积极互动和支持。</li></ul><h4 id="识别的错误、误解或遗漏的信息" tabindex="-1">识别的错误、误解或遗漏的信息： <a class="header-anchor" href="#识别的错误、误解或遗漏的信息" aria-label="Permalink to &quot;识别的错误、误解或遗漏的信息：&quot;">​</a></h4><ul><li>原始总结中未提及NVMe-oF的具体性能测试结果和细节。</li><li>原始字幕中未明确提及项目状态和后续行动计划。</li></ul><h4 id="改进后的总结" tabindex="-1">改进后的总结： <a class="header-anchor" href="#改进后的总结" aria-label="Permalink to &quot;改进后的总结：&quot;">​</a></h4><ul><li>在内容摘要中增加了NVMe-oF的具体性能测试结果和细节。</li><li>在会议内容总结中增加了项目状态和后续行动计划。</li></ul>',15)])])}const d=a(i,[["render",t]]);export{_ as __pageData,d as default};
